// ============================================================
// n8n Code Node — Extract Code & System Prompts as Binary Files
// Mode: "Run Once for All Items"  (set this in the node's settings)
// ============================================================
// INPUT   One or more items whose JSON is (or contains) an n8n
//         workflow object — i.e. it has a `.nodes` array. Works with:
//           - the built-in "n8n" node's "Get a workflow" output
//           - a workflow .json export read + parsed
//
// OUTPUT  ONE item PER extracted file — nothing else, so downstream
//         nodes can map 1:1 over the array:
//           -> json: {}  (n8n requires every item to have a json key
//              by design; there's no way to omit it entirely, so it's
//              left empty on purpose — functionally these items are
//              just the files, no other data attached)
//           -> binary.data: the real file (filename, extension and
//              mime type are embedded in the binary object itself by
//              prepareBinaryData), ready for "Write Binary File to
//              Disk", email attachment, S3 upload, etc.
//
//         For every workflow processed, the array also includes ONE
//         extra file: the complete workflow JSON itself (the same
//         object that came in), named "<workflow name>.json" — same
//         pure-binary shape as every other item.
//
//         Extension logic:
//           system prompt (from an AI node)        -> .md
//           Code node running in Python             -> .py
//           Code node running in JavaScript          -> .js
//         Filename = the node's name as it appears on the canvas.
// ============================================================

function getWorkflowObject(item) {
  const j = item.json || {};
  if (Array.isArray(j.nodes)) return j;
  if (j.workflow && Array.isArray(j.workflow.nodes)) return j.workflow;
  if (j.data && Array.isArray(j.data.nodes)) return j.data;
  return null;
}

function sanitizeFileName(name) {
  return String(name).replace(/[\\/:*?"<>|\x00-\x1F]/g, '_').trim() || 'untitled';
}

// Recursively search a node's `parameters` for system-prompt style
// fields, without hard-coding every single AI node type/version.
function findSystemPrompts(obj, out) {
  if (!obj || typeof obj !== 'object') return;

  if (Array.isArray(obj)) {
    for (const entry of obj) {
      if (entry && typeof entry === 'object') {
        const role = (entry.role || entry.type || '').toString().toLowerCase();
        const content = entry.content ?? entry.message ?? entry.text;
        if (role === 'system' && typeof content === 'string' && content.trim()) {
          out.push(content);
        }
      }
      findSystemPrompts(entry, out);
    }
    return;
  }

  for (const [key, value] of Object.entries(obj)) {
    const k = key.toLowerCase();
    if (
      (k === 'systemmessage' || k === 'systemprompt' || k === 'system') &&
      typeof value === 'string' &&
      value.trim()
    ) {
      out.push(value);
    } else if (typeof value === 'object') {
      findSystemPrompts(value, out);
    }
  }
}

// Pull raw source code out of a node's parameters — covers the
// current Code node, legacy Function / FunctionItem nodes, and
// LangChain "code" style tool nodes.
function findCode(node) {
  const p = node.parameters || {};
  const lang = (p.language || '').toLowerCase();

  if (typeof p.pythonCode === 'string' && p.pythonCode.trim()) {
    return { content: p.pythonCode, language: 'python' };
  }
  if (typeof p.jsCode === 'string' && p.jsCode.trim()) {
    return { content: p.jsCode, language: 'javascript' };
  }
  if (typeof p.functionCode === 'string' && p.functionCode.trim()) {
    return { content: p.functionCode, language: 'javascript' };
  }
  if (typeof p.code === 'string' && p.code.trim()) {
    return { content: p.code, language: lang === 'python' ? 'python' : 'javascript' };
  }
  return null;
}

const EXT = { javascript: 'js', python: 'py', markdown: 'md' };
const MIME = {
  javascript: 'text/javascript',
  python: 'text/x-python',
  markdown: 'text/markdown',
  json: 'application/json',
};

const usedNames = new Map(); // collision-avoidance within this run
function reserveFileName(baseName, ext) {
  const key = `${baseName}.${ext}`.toLowerCase();
  const count = usedNames.get(key) || 0;
  usedNames.set(key, count + 1);
  return count === 0 ? `${baseName}.${ext}` : `${baseName} (${count + 1}).${ext}`;
}

const results = [];

for (const item of $('Extract from File').all()) {
  const workflow = getWorkflowObject(item);
  if (!workflow) continue;

  const workflowName = workflow.name || 'Untitled workflow';
  const nodes = Array.isArray(workflow.nodes) ? workflow.nodes : [];

  // ---- Extra file: the whole workflow JSON, same shape as the rest ----
  {
    const wfFileName = reserveFileName(sanitizeFileName(workflowName), 'json');
    const wfBuffer = Buffer.from(JSON.stringify(workflow, null, 2), 'utf-8');
    const wfBinaryData = await this.helpers.prepareBinaryData(
      wfBuffer,
      wfFileName,
      MIME.json
    );
    results.push({
      json: {},
      binary: { data: wfBinaryData },
    });
  }

  // ---- Collect every file to extract, then emit one binary item each ----
  for (const node of nodes) {
    const nodeName = node.name || node.id || 'unnamed-node';
    const safeName = sanitizeFileName(nodeName);
    const filesForThisNode = [];

    const code = findCode(node);
    if (code) {
      filesForThisNode.push({
        fileName: reserveFileName(safeName, EXT[code.language]),
        content: code.content,
        language: code.language,
      });
    }

    const prompts = [];
    findSystemPrompts(node.parameters, prompts);
    for (const prompt of [...new Set(prompts)]) {
      filesForThisNode.push({
        fileName: reserveFileName(safeName, EXT.markdown),
        content: prompt,
        language: 'markdown',
      });
    }

    for (const f of filesForThisNode) {
      const buffer = Buffer.from(f.content, 'utf-8');
      const binaryData = await this.helpers.prepareBinaryData(
        buffer,
        f.fileName,
        MIME[f.language]
      );

      results.push({
        json: {}, // intentionally empty — see note at the top of this file
        binary: { data: binaryData },
      });
    }
  }
}

return results;

